        if len(plates) >= a:
            operations.append((1, a))
            plates = plates[:-a]
        else:
            # If not enough plates to move 'a' plates, check if we can move 'b' plates from the intermediate stack to the dryer
            if len(plates) >= b:
                operations.append((2, b))
                plates = plates[:-b]
            else:
